package com.nametag.api;
import com.fasterxml.jackson.core.type.TypeReference; import com.fasterxml.jackson.databind.ObjectMapper; import com.nametag.domain.animal.model.*; import com.nametag.domain.match.model.*; import com.nametag.domain.settle.model.*; import com.nametag.domain.evaluate.model.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.file.*; import java.util.*;
@Service public class NametagService { private final ObjectMapper mapper; private final List<RawAnimal> animals; private final List<Profile> personas;
 public NametagService(ObjectMapper mapper,@Value("${nametag.fixture-dir:./fixtures}")String dir)throws Exception{this.mapper=mapper;this.animals=mapper.readValue(Files.readString(Path.of(dir,"animals.json")),new TypeReference<>(){});this.personas=mapper.readValue(Files.readString(Path.of(dir,"personas.json")),new TypeReference<>(){});}
 public MatchOutput match(Profile p){return MatchEngine.match(p,animals.stream().map(a->AnimalDeriver.derive(a,2026)).toList());} public SettlePlan settle(Profile p){return SettlePlanBuilder.build(p);} public Evaluation evaluate(){return Evaluator.evaluate(personas,animals);} public List<RawAnimal> animals(){return animals;} public List<String> questions(String id){return animals.stream().filter(a->a.desertionNo().equals(id)).findFirst().map(a->ShelterQuestions.forAnimal(AnimalDeriver.derive(a,2026))).orElse(List.of());}}
